from solution import Entry, Report, solve

assert solve([], 0) == Report(0, (-1), 0), 'fixture 0'
assert solve([], 5) == Report(0, (-1), 0), 'fixture 1'
assert solve([], 1) == Report(0, (-1), 0), 'fixture 2'
assert solve([Entry(11, 15, 3)], 2) == Report(3, 11, 1), 'fixture 3'
assert solve([Entry(3, 8, 3), Entry(6, 12, 5)], 3) == Report(8, 6, 1), 'fixture 4'
assert solve([Entry(10, 13, 1), Entry(0, 2, 1), Entry(1, 6, 4)], 4) == Report(5, 1, 1), 'fixture 5'
assert solve([Entry(3, 6, 3), Entry(5, 10, 2), Entry(7, 8, 2), Entry(6, 13, 3)], 5) == Report(7, 7, 1), 'fixture 6'
assert solve([Entry(0, 5, 5), Entry(9, 12, 2), Entry(6, 7, 2), Entry(4, 5, 4), Entry(8, 15, 2)], 6) == Report(9, 4, 1), 'fixture 7'
assert solve([Entry(1, 8, 5), Entry(7, 13, 5), Entry(5, 9, 1), Entry(10, 14, 5), Entry(9, 11, 5), Entry(0, 2, 3)], 7) == Report(15, 10, 4), 'fixture 8'
assert solve([Entry(1, 5, 2), Entry(0, 1, 4), Entry(6, 12, 4), Entry(11, 12, 5), Entry(7, 14, 2), Entry(5, 12, 1), Entry(0, 3, 2)], 8) == Report(12, 11, 1), 'fixture 9'
assert solve([Entry(10, 14, 2), Entry(10, 17, 1), Entry(7, 8, 3), Entry(9, 11, 4), Entry(11, 12, 4), Entry(9, 12, 4), Entry(2, 3, 3), Entry(3, 9, 3)], 1) == Report(11, 10, 6), 'fixture 10'
assert solve([Entry(2, 9, 5), Entry(5, 7, 4), Entry(4, 6, 3), Entry(4, 11, 5), Entry(5, 9, 2), Entry(10, 11, 3), Entry(0, 4, 1), Entry(6, 11, 3), Entry(3, 4, 1)], 2) == Report(19, 5, 6), 'fixture 11'
assert solve([Entry(7, 8, 1), Entry(2, 7, 1), Entry(1, 7, 2), Entry(11, 14, 4), Entry(9, 12, 1), Entry(5, 8, 5), Entry(8, 11, 3), Entry(2, 4, 1), Entry(4, 6, 3), Entry(8, 11, 5)], 3) == Report(11, 5, 7), 'fixture 12'
assert solve([Entry(6, 12, 4), Entry(0, 2, 4), Entry(7, 9, 1), Entry(4, 5, 5), Entry(6, 8, 2), Entry(8, 14, 5), Entry(9, 14, 2), Entry(9, 14, 2), Entry(3, 7, 2), Entry(2, 8, 2), Entry(7, 11, 3)], 4) == Report(16, 9, 5), 'fixture 13'
assert solve([Entry(9, 12, 3), Entry(5, 12, 2), Entry(3, 8, 1), Entry(5, 7, 2), Entry(4, 6, 2), Entry(9, 10, 2), Entry(1, 8, 4), Entry(11, 15, 1), Entry(6, 10, 2), Entry(8, 9, 4), Entry(1, 6, 4), Entry(6, 12, 3)], 5) == Report(15, 5, 8), 'fixture 14'
assert solve([], 6) == Report(0, (-1), 0), 'fixture 15'
assert solve([Entry(1, 3, 4)], 7) == Report(4, 1, 0), 'fixture 16'
assert solve([Entry(0, 4, 4), Entry(2, 5, 1)], 8) == Report(5, 2, 0), 'fixture 17'
assert solve([Entry(8, 10, 4), Entry(7, 10, 1), Entry(7, 9, 2)], 1) == Report(7, 8, 2), 'fixture 18'
assert solve([Entry(4, 9, 3), Entry(8, 12, 5), Entry(0, 3, 3), Entry(8, 15, 5)], 2) == Report(13, 8, 3), 'fixture 19'
assert solve([Entry(10, 12, 1), Entry(10, 11, 4), Entry(6, 9, 3), Entry(10, 14, 1), Entry(8, 9, 1)], 3) == Report(6, 10, 2), 'fixture 20'
assert solve([Entry(5, 9, 1), Entry(3, 7, 3), Entry(4, 10, 1), Entry(9, 16, 5), Entry(10, 12, 5), Entry(9, 16, 1)], 4) == Report(11, 10, 3), 'fixture 21'
assert solve([Entry(3, 8, 2), Entry(3, 5, 3), Entry(0, 6, 5), Entry(2, 9, 4), Entry(8, 13, 1), Entry(8, 10, 1), Entry(10, 11, 1)], 5) == Report(14, 3, 3), 'fixture 22'
assert solve([Entry(7, 14, 3), Entry(8, 15, 1), Entry(2, 9, 2), Entry(10, 11, 3), Entry(3, 5, 1), Entry(5, 7, 2), Entry(10, 12, 3), Entry(4, 9, 4)], 6) == Report(10, 8, 5), 'fixture 23'
assert solve([Entry(0, 2, 3), Entry(2, 4, 3)], 3) == Report(3, 0, 0), 'fixture 24'
assert solve([Entry(2, 4, 5), Entry(0, 2, 5), Entry(0, 2, 1)], 5) == Report(6, 0, 1), 'fixture 25'
assert solve([Entry(4, 8, 2), Entry(0, 4, 3), Entry(2, 6, 4), Entry(2, 3, 1)], 5) == Report(8, 2, 2), 'fixture 26'
